/* 夜間主題 */
  :root {
  /* ---------- 1. 全局聊天背景 ---------- */
  --chat-bg-color: #1A1A1A!important;
  --chat-bg-image: none!important;
  --chat-bg-size: cover;
  --chat-bg-position: center;

  /* ---------- 2. 頂欄基礎參數 ---------- */
  --chat-header-bg: #1A1A1A!important;
  --chat-header-height: 91px;
  --chat-header-border: none;
  --chat-header-shadow: none;
  --chat-header-blur: 1000px;

  /* ---------- 3. 角色標題（名字） ---------- */
  --title-color: #FFFFFF!important;
  --title-weight: 700;
  --title-size: 17px;
  --title-top: 4px;
  --title-left: 49px;

  /* ---------- 4. 未讀數字徽章 ---------- */
  --unread-color: #FFFFFF!important;
  --unread-size: 17px;
  --unread-weight: 800;
  --unread-display: flex;
  --unread-bg: transparent;
  --unread-border: none; /* 灰色邊框，後續可改none */
  --unread-top: 1px;
  --unread-left: 17.8px;

  /* ---------- 5. 返回按鈕 ---------- */
  --btn-back-w: 20px;
  --btn-back-h: 25px;
  --btn-back-left: -0.8px;
  --btn-back-top: 4.6px;
  --btn-back-icon: url('https://i.ibb.co/xKMDvfGr/IMG-4044.png')!important;

  /* ---------- 6. 電話按鈕 ---------- */
  --btn-phone-w: 20px;
  --btn-phone-h: 20px;
  --btn-phone-right: 3.5px;
  --btn-phone-top: 3.6px;
  --btn-phone-icon: url('https://i.ibb.co/Ldh6sNJq/IMG-4045.png')!important;

  /* ---------- 7. 影片按鈕 ---------- */
  --btn-video-w: 20px;
  --btn-video-h: 20px;
  --btn-video-right: 48px;
  --btn-video-top: 4px;
  --btn-video-icon: url('https://i.ibb.co/xKQ0jTsY/IMG-4046.png')!important;

  /* ---------- 8. 設置(info)按鈕 ---------- */
  --btn-info-w: 20px;
  --btn-info-h: 20px;
  --btn-info-right: 6px;
  --btn-info-top: 4px;
  --btn-info-icon: url('https://i.ibb.co/czmcnv7/IMG-4048.png')!important;

  /* ---------- 9. 中間裝飾圖示 ---------- */
  --deco-w: 20px;
  --deco-h: 20px;
  --deco-right: 65px;
  --deco-top: 22.5px;
  --deco-icon: url('https://i.ibb.co/KxvStnYW/IMG-4047.png')!important;

  --chat-messages-gap: 0px;
  --chat-messages-padding: 5px 0px;

  --plain-gap-within-group: 11px;
  --plain-gap-between-groups: 11px;

  --status-color: #898989!important;
  --status-size: 10px;
  --status-read-color: #898989!important;
  --status-sent-color: #898989!important;  /* 修復：從透明改為可見灰色 */

  --wa-me-meta-color: #898989!important;
  --wa-them-meta-color: #898989!important;
  --wa-me-check-read-color: #898989!important;
  --wa-bubble-me: #6DE67B;
  --wa-bubble-them: #2A2A2A;
  /* 底欄回覆預覽欄顏色 */
  --reply-bar-accent: #FFFFFF!important;    /* 引用對象名稱色 */
  --reply-bar-text-color: #949494!important;  /* 引用內容文字色 */

  /* === 聊天頂部簡介卡  === */
  --profile-card-name-color: #FFFFFF!important;
  --profile-card-subtitle-color: #FFFFFF!important;
  --profile-card-btn-bg: #3F3F3F!important;
  --profile-card-btn-color: #FFFFFF!important;

/* ====================== 圖片訊息美化 ====================== */
  /* ----- 通用圖片設定 ----- */
  --image-msg-radius: 8px;          /* 圖片圓角 */
  --image-msg-shadow: none;         /* 圖片陰影 */
  --image-msg-border: none;         /* 圖片邊框 */
  /* ----- 我方傳送的圖片：最大寬度與我方普通氣泡一致（262px），確保右邊距對齊 ----- */
  --image-me-max-width: 262px;
  --image-me-radius: initial;
  --image-me-shadow: initial;
  --image-me-border: initial;
  --image-me-filter: initial;
  --image-me-opacity: initial;
  /* ----- 對方傳送的圖片：最大寬度與對方普通氣泡一致（270px），確保左邊距對齊 ----- */
  --image-them-max-width: 270px;
  --image-them-radius: initial;
  --image-them-shadow: initial;
  --image-them-border: initial;
  --image-them-filter: initial;
  --image-them-opacity: initial;

  /* ===== 波形顏色 ===== */
  --voice-me-bar-active: #2B5A30 !important;
  --voice-me-bar-inactive: #5fc86b !important;
  --voice-them-bar-active: #FFFFFF !important;
  --voice-them-bar-inactive: #3F3F3F !important;

  /* ===== 文字/時間戳顏色 ===== */
  --voice-me-color: #111111;
  --voice-them-color: #FFFFFF;

  /* ===== 間距配置 ===== */
  --voice-container-gap: 2px;
  --voice-controls-gap: -5px;

  /* ===== 時間戳樣式 ===== */
  --voice-duration-size: 12px;
  --voice-duration-weight: 500;

  /* ===== 轉寫文字框 ===== */
  --voice-transcription-bg: transparent;
  --voice-transcription-margin-top: -1px;
  --voice-transcription-padding: 2px 0px 0 0px;
  --voice-transcription-line-height: 1.2;
  --voice-transcription-radius: 0px;
  --voice-transcription-border: none;
  --voice-transcription-animation: none;
  --voice-transcription-size: initial;

  /* ===== 波形 + 播放按鈕 全面壓矮 ===== */
  --voice-bar-min-width: 2px;
  --voice-bar-max-width: 2px;
  --voice-waveform-height: 28px;        /* 波形從28→20，直接砍8px */
  --voice-play-btn-size: 19px;          /* 播放按鈕縮小，避免撐高整行 */
}

/* ========== 二、隱藏指定元素 ========== */
.header-avatar-container {
  display: none !important;
}

.nuo-chat-header-unread-dot {
