}

/* ========== 七、未讀數字徽章（相對定位·不裁切版） ========== */
/* 參考新CSS方法，用相對定位，父容器全部解鎖，數字不會被裁 */

.nuo-chat-header-unread-num {
  display: var(--unread-display) !important;
  color: var(--unread-color) !important;
  font-size: var(--unread-size) !important;
  font-weight: var(--unread-weight) !important;
  background: var(--unread-bg) !important;
  border: var(--unread-border) !important;
  top: var(--unread-top) !important;
  left: var(--unread-left) !important;
  right: auto !important;
  box-shadow: none !important;
  min-width: unset !important;
  width: fit-content !important;
  height: auto !important;
  padding: 2px 4px !important;
  line-height: 1 !important;
  overflow: visible !important;
  white-space: nowrap !important;
  text-align: left !important;      /* 關鍵：確保文字從左邊開始排列 */
  position: absolute !important;    /* 用 absolute 鎖定左邊起點，不受內容寬度影響 */
  z-index: 99 !important;
}

/* ========== 八、中間裝飾圖示 ========== */
.chat-header-custom::after {
  content: "";
  position: absolute;
  top: calc(50% + var(--deco-top));
  transform: translateY(-50%);
  right: var(--deco-right);
  width: var(--deco-w);
  height: var(--deco-h);
  background-image: var(--deco-icon);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  pointer-events: none;
  z-index: 2;
}

