  font-weight: 700 !important;
  /* 文字顏色（可換成任何顏色值） */
  color: #5ac463 !important;
  /* 字間距（調大文字散開，調小緊湊） */
  letter-spacing: 0.25px !important;
  display: inline-block !important;
}
/* ============================================================
   █ 金額數字 — 位於標籤下方，大號粗體
   ============================================================ */
body .msg-transfer-amount {
  position: absolute !important;
  z-index: 2 !important;
